// Run Once for All Items
for (const item of $input.all()) {
  const binaryKey = 'data'; // must match the binary property name from "Generate an image"
  const binary = item.binary?.[binaryKey];

  if (!binary) {
    throw new Error(`No binary data found on key "${binaryKey}". Check the binary property name from the previous node.`);
  }

  const mimeType = binary.mimeType || 'image/png';

  // Build a base64 data URL from the binary
  item.json.imageUrl = `data:${mimeType};base64,${binary.data}`;
  item.json.fileName = binary.fileName || 'generated-image.png';
  item.json.mimeType = mimeType;
  item.json.fileSizeBytes = binary.fileSize || null;

  // item.binary stays untouched — the binary file still flows through this node
}

return $input.all();
